package com.tms.billing.service;
import com.tms.basic.entity.RateRule; import com.tms.basic.mapper.RateRuleMapper; import com.tms.billing.mapper.FreightBillMapper; import com.tms.common.CodeGenerator; import com.tms.order.entity.TransportOrder; import org.junit.jupiter.api.Test; import org.mockito.Mockito; import java.math.BigDecimal; import java.util.Arrays; import static org.junit.jupiter.api.Assertions.*;
class BillingServiceTest {
 @Test void weightMinChargeAndCarrierPriority(){RateRuleMapper rm=Mockito.mock(RateRuleMapper.class);FreightBillMapper bm=Mockito.mock(FreightBillMapper.class);RateRule generic=new RateRule();generic.setCode("G");generic.setChargeType("WEIGHT");generic.setFirstUnit(new BigDecimal("3"));generic.setFirstPrice(new BigDecimal("10"));generic.setAddUnit(BigDecimal.ONE);generic.setAddPrice(new BigDecimal("1.5"));generic.setMinCharge(new BigDecimal("10"));generic.setStatus("ENABLED");generic.setPriority(20);RateRule carrier=new RateRule();carrier.setCode("C");carrier.setCarrierCode("SF");carrier.setChargeType("WEIGHT");carrier.setFirstUnit(BigDecimal.ONE);carrier.setFirstPrice(new BigDecimal("12"));carrier.setAddUnit(BigDecimal.ONE);carrier.setAddPrice(new BigDecimal("3"));carrier.setMinCharge(new BigDecimal("12"));carrier.setStatus("ENABLED");carrier.setPriority(1);Mockito.when(rm.selectList(Mockito.any())).thenReturn(Arrays.asList(generic,carrier));BillingService s=new BillingService(rm,bm,new CodeGenerator());TransportOrder o=new TransportOrder();o.setChargeableWeightKg(new BigDecimal("3"));BillingService.CalcResult r=s.calc("SF","WEIGHT",o,BigDecimal.ZERO);assertEquals("C",r.getRule().getCode());assertEquals(0,new BigDecimal("18").compareTo(r.getAmount()));}
 @Test void distance(){RateRule r=new RateRule();r.setCode("D");r.setCarrierCode("SELF01");r.setChargeType("DISTANCE");r.setFirstUnit(new BigDecimal("50"));r.setFirstPrice(new BigDecimal("300"));r.setAddUnit(new BigDecimal("10"));r.setAddPrice(new BigDecimal("40"));r.setMinCharge(new BigDecimal("300"));r.setStatus("ENABLED");RateRuleMapper rm=Mockito.mock(RateRuleMapper.class);Mockito.when(rm.selectList(Mockito.any())).thenReturn(Arrays.asList(r));BillingService s=new BillingService(rm,Mockito.mock(FreightBillMapper.class),new CodeGenerator());BillingService.CalcResult out=s.calc("SELF01","DISTANCE",new TransportOrder(),new BigDecimal("200"));assertEquals(new BigDecimal("900"),out.getAmount());}
}
